INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65697466', 65697466, 'analyze_legacy', 'Kementerian Hukum', 'central', 'DIREKTORAT JENDERAL ADMINISTRASI HUKUM UMUM', 'Pengadaan Belanja Jasa Kegiatan Quality Assurance (QA), Quality Control (QC) dan Source Code Audit (SCA) pada Direktorat Teknologi Informasi, Direktorat Jenderal Administrasi Hukum Umum Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 600000000, 'January 2026', 'APBN - PINJAMAN DALAM NEGERI (E)', 0, 1, '3 Paket', 'Pelaksanaan pengujian kualitas menyeluruh terhadap aplikasi melalui metode penjaminan mutu dan kontrol kualitas serta melakukan audit mendalam terhadap baris kode program. Fokus utama kegiatan ini adalah untuk mengidentifikasi celah keamanan, kesalahan logika, maupun inefisiensi algoritma pada kode sumber sebelum sistem diimplementasikan atau diperbarui guna memastikan aplikasi yang dirilis memiliki standar keamanan dan performa yang tinggi.', 'Tenaga ahli wajib memiliki keahlian dalam penggunaan alat audit kode otomatis maupun manual serta memiliki sertifikasi profesional di bidang pengujian perangkat lunak atau audit keamanan sistem. Spesifikasi pekerjaan menuntut kemampuan menyusun laporan temuan teknis yang mendetail beserta rekomendasi perbaikan yang solutif, serta pengalaman dalam melakukan audit sistem informasi pada lingkungan infrastruktur kritis pemerintahan agar hasil audit akuntabel.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2300985);
