INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65702492', 65702492, 'analyze_legacy', 'Kota Tangerang', 'kabkota', 'DINAS PEKERJAAN UMUM DAN PENATAAN RUANG', 'PEMUTAKHIRAN DATA JALAN LINGKUNGAN PADA KECAMATAN LARANGAN DAN CILEDUG', 'Jasa Konsultansi', 'Seleksi', 'Banten, Tangerang (Kota)', 363429200, 'February 2026', 'APBD', 1, 1, '1', 'Lingkup pelaksanaan kegiatan ini meliputi : a. Persiapan dan koordinasi Pengumpulan data sekunder database jalan eksisting serta koordinasi dengan pihak kelurahan dan kecamatan dalam rangka pelaksanaan survei dan validasi lapangan. b. Identifikasi ruas jalan lingkungan Identifikasi seluruh ruas jalan lingkungan, baik ruas yang telah tercatat dalam database jalan maupun ruas jalan baru yang belum terdata, sesuai kondisi eksisting di lapangan. c. Pemutakhiran data ruas jalan lingkungan Pemutakhiran data geometri, atribut, dan kondisi fisik ruas jalan yang telah terdata dalam database jalan lingkungan dengan panjang kurang lebih 417 km. d. Pendataan ruas jalan lingkungan baru Pengukuran dan pendataan ruas jalan lingkungan baru termasuk penetapan kode ruas jalan yang belum tercantum dalam database jalan lingkungan. Sumber identifikasi ruas jalan baru tersebut meliputi: - Hasil digitasi jalan lingkungan kegiatan terdahulu; - Hasil data pembangunan jalan lingkungan baru dari Bidang Bina Marga DPUPR Kota Tangerang; - Hasil observasi dan temuan terkini di lapangan. e. Pengukuran dan pendataan geometri serta data pelengkap jalan Pekerjaan meliputi survei topografi dan kelengkapan jalan, pemeriksaan kondisi jalan, saluran/drainase, jembatan, serta utilitas jalan yang mencakup jenis dan materialnya pada ruas-ruas jalan lingkungan sesuai kondisi eksisting di lapangan. f. Penyusunan Kartu Database Jalan Lingkungan Hasil pekerjaan disusun dan disajikan dalam bentuk Kartu Database Jalan Lingkungan, yang mencakup data geometri, atribut, kondisi jalan, serta dilengkapi gambar teknis : - gambar memanjang (long section) jalan dan saluran - gambar potongan melintang (cross section) jalan interval 50 meter. - dokumentasi foto kondisi jalan setiap interval ±25 meter. g. Pengolahan, Validasi, dan Penyajian Data Seluruh hasil pemeriksaan lapangan dilakukan input, pengolahan, dan penyajian ke dalam basis data berbasis Sistem Informasi Geografis (SIG/GIS), serta dilakukan validasi hasil pendataan bersama pihak kelurahan atau kecamatan sebelum ditetapkan sebagai data akhir pemutakhiran database jalan lingkungan.', '1 Orang Team Leader Tenaga Ahli Teknik Jalan Ahli Muda S1 Pengalaman 2 Tahun, 1Orang Tenaga Ahli Teknik Geodesi Ahli Muda S1 Pengalaman 1 Tahun; 6 Orang Tenaga Pendukung Surveyor; 3 Orang Tenaga Pendukung Operator CAD/CAM.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2309513);
